DO $$
declare
    v_dataset_id uuid;
begin
    select id into v_dataset_id
    from ores_dq_datasets_tbl
    where code = 'acme.acme_us.report_definitions'
      and valid_to = ores_utility_infinity_timestamp_fn();

    if v_dataset_id is null then
        raise exception 'Dataset not found: acme.acme_us.report_definitions. Run acme_dataset_populate.sql first.';
    end if;

    delete from ores_dq_report_definitions_artefact_tbl
    where dataset_id = v_dataset_id;

    insert into ores_dq_report_definitions_artefact_tbl (
        dataset_id, tenant_id, id, version, name, description, report_type, schedule_expression, concurrency_policy, display_order, tier, applicable_jurisdiction, regulatory_book_type, cut_kind_code
    )
    values
        (v_dataset_id, ores_utility_system_tenant_id_fn(), gen_random_uuid(), 1, 'Data Quality Completeness', 'Validates all required market data, reference data, and trade data is present across the entity. Flags gaps in instrument codes, missing curve pillars, stale fixings, and orphaned trades. Runs early so downstream analytics have a clean data baseline.', 'risk', '0 5 * * 1-5', 'skip', 5, 'common', null, null, null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), gen_random_uuid(), 1, 'Audit Trail Summary', 'Daily summary of all create, update, and delete operations across all domain entities for the entity. Broken down by service, actor, and change reason category. Supports SOX and SOC 2 compliance requirements for change logging.', 'risk', '0 6 * * 1-5', 'skip', 15, 'common', null, null, null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), gen_random_uuid(), 1, 'SA-CCR Exposure', 'Standardised Approach for Counterparty Credit Risk: computes Exposure-at-Default (EAD), Replacement Cost (RC), and Potential Future Exposure (PFE) per netting set under Basel III/IV supervisory rules. Required for Risk-Weighted Asset (RWA) and leverage ratio calculations. Replaces the legacy Current Exposure Method (CEM).', 'risk', '0 6 * * 1-5', 'skip', 20, 'regulatory', null, null, null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), gen_random_uuid(), 1, 'Leverage Ratio', 'Computes the Basel III leverage ratio: Tier 1 capital divided by total exposure measure (on- and off-balance sheet, derivatives, SFTs). Alerts if the ratio approaches the 3% minimum threshold. Required for all regulated entities under CRR/Basel III pillar 2.', 'risk', '0 6 * * 1-5', 'skip', 25, 'regulatory', null, null, null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), gen_random_uuid(), 1, 'FRTB SA Capital', 'Fundamental Review of the Trading Book — Standardised Approach: computes market risk capital using supervisory-prescribed sensitivity-based method (SBM) across delta, vega, and curvature risk for all risk classes (GIRR, CSR, FX, EQ, CMDTY). Floor model and fallback for desks not approved for IMA.', 'risk', '0 7 * * 1-5', 'skip', 30, 'regulatory', null, 'Trading', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), gen_random_uuid(), 1, 'Liquidity Coverage', 'Liquidity Coverage Ratio (LCR): High-Quality Liquid Assets divided by net cash outflows over a 30-day stress horizon. Flags when HQLA buffer drops below 100% minimum. Required under Basel III for all regulated deposit-taking and investment firms.', 'risk', '0 7 * * 1-5', 'skip', 35, 'regulatory', null, null, null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), gen_random_uuid(), 1, 'Large Exposures', 'Monitors single-counterparty exposure concentration against the 25% of Tier 1 capital regulatory limit. Aggregates across all netting sets, SFTs, and indirect exposures for each legal entity counterparty. Produces breach alerts and a top-20 concentration report.', 'risk', '0 7 * * 1-5', 'skip', 40, 'regulatory', null, null, null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), gen_random_uuid(), 1, 'CFTC Swap Data Reporting', 'Swap transaction reporting under CFTC Part 43/45 rules. Produces real-time public and regulatory reports for all swap transactions to a registered Swap Data Repository (SDR). Covers all CFTC-jurisdiction swaps. US entities only.', 'risk', '0 8 * * 1-5', 'skip', 50, 'regulatory', 'US', null, null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), gen_random_uuid(), 1, 'Model Calibration', 'Calibrates interest rate, FX, and volatility models (LGM, Hull-White, SABR, Black-Scholes) to live market data. Outputs calibrated parameters and fit quality metrics (RMSE). Must run before exposure simulation, XVA, and sensitivity analytics that depend on calibrated model parameters.', 'risk', '0 5 * * 1-5', 'skip', 80, 'trading', null, null, null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), gen_random_uuid(), 1, 'Yield Curves', 'Bootstraps discount and projection yield curves from market instruments (deposits, FRAs, swaps, OIS, bonds). Outputs the full term structure of interest rates used by all pricing engines. Essential prerequisite for NPV, sensitivity, and Monte Carlo exposure analytics.', 'risk', '0 5 * * 1-5', 'skip', 85, 'trading', null, null, null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), gen_random_uuid(), 1, 'FX Spot Rates', 'Loads and validates FX spot rates for all active currency pairs from market data feeds. Provides consistent FX conversion for multi-currency portfolio valuation, sensitivities, and regulatory capital calculations that require base-currency aggregation.', 'risk', '0 5 * * 1-5', 'skip', 90, 'trading', null, null, null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), gen_random_uuid(), 1, 'Credit Curves', 'Bootstraps CDS-implied survival probability curves and hazard rate curves for each counterparty and entity. Calibrates credit models (Jarrow-Turnbull, Hull-White credit) to market spreads. Prerequisite for CVA, DVA, FVA, and regulatory SA-CVA capital computations.', 'risk', '0 5 * * 1-5', 'skip', 100, 'trading', null, null, null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), gen_random_uuid(), 1, 'NPV', 'Full mark-to-market portfolio valuation producing present values for all active trades. Applies validated yield curves and FX rates. Provides the daily P&L baseline, feeds downstream sensitivities, and serves as the reference for risk-neutral pricing across all asset classes.', 'risk', '0 6 * * 1-5', 'skip', 105, 'trading', null, null, null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), gen_random_uuid(), 1, 'Cashflows', 'Projects all future contractual cashflows across the portfolio: fixed, floating, contingent, and collateral flows. Used for liquidity risk, funding cost estimation, hedge effectiveness testing, and IFRS 9 / IFRS 7 cashflow disclosure.', 'risk', '0 6 * * 1-5', 'skip', 110, 'trading', null, null, null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), gen_random_uuid(), 1, 'Delta and Gamma', 'Computes first-order (delta) and second-order (gamma) price sensitivities to interest rates, FX, and credit spreads using bump-and-revalue. Produces risk ladder reports by tenor bucket and currency. Feeds hedging, P&L attribution, and FRTB sensitivity-based method capital.', 'risk', '0 7 * * 1-5', 'skip', 115, 'trading', null, null, null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), gen_random_uuid(), 1, 'Bucketed DV01', 'Key-rate DV01 (dollar value of one basis point) decomposition across standardised tenor buckets (1M, 3M, 6M, 1Y, 2Y, 5Y, 10Y, 20Y, 30Y). Provides a granular interest rate risk profile per currency, netting set, and book. Core input to duration management and FRTB delta capital.', 'risk', '0 7 * * 1-5', 'skip', 125, 'trading', null, null, null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), gen_random_uuid(), 1, 'Exposure', 'Monte Carlo simulation of future exposure profiles (EE, PFE, EPE, ENE) at the netting-set level using risk-factor simulation. Drives CVA/DVA valuation, regulatory capital under SA-CCR, and internal credit limits. Computationally intensive; uses queue concurrency to serialise with other long-running reports.', 'risk', '0 8 * * 1-5', 'queue', 130, 'trading', null, null, null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), gen_random_uuid(), 1, 'CVA/DVA/FVA', 'Composite report computing all three valuation adjustments: Credit VA (counterparty default risk), Debit VA (own default risk), and Funding VA (uncollateralised funding cost). Uses exposure profiles from the Exposure report and credit curves from Credit Curves. Essential for IFRS 13 fair value.', 'risk', '0 8 * * 1-5', 'queue', 135, 'trading', null, null, null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), gen_random_uuid(), 1, 'Stressed VaR', 'VaR computed over a stressed historical window (2008 financial crisis or COVID-2020) at 99% confidence, 10-day holding period. Required as a capital add-on under Basel 2.5 IMA. Uses full revaluation for non-linear exposures.', 'risk', '0 8 * * 1-5', 'skip', 140, 'trading', null, 'Trading', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), gen_random_uuid(), 1, 'P&L Attribution', 'Daily decomposition of P&L into risk-factor components: delta, gamma, vega, theta, carry, and unexplained residual. Required for FRTB IMA back-testing and P&L attribution test (PLAT) compliance. Compares hypothetical P&L against actual P&L to validate model quality.', 'risk', '0 16 * * 1-5', 'skip', 145, 'trading', null, 'Trading', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), gen_random_uuid(), 1, 'Intraday Risk Monitor', 'Real-time risk snapshot updated every 30 minutes during trading hours. Displays key risk metrics: PV, delta ladder, top 10 P&L movers, VaR estimate, and limit-utilisation gauges. Uses queue concurrency to serialise updates. Provides traders and desk heads with continuous risk visibility between end-of-day analytic runs.', 'risk', '*/30 8-17 * * 1-5', 'queue', 150, 'trading', null, null, 'LIVE'),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), gen_random_uuid(), 1, 'Headline Position', 'Displays the most important Greeks across the entire deal set for a book or portfolio. The primary real-time risk overview report for traders and risk managers. Configurable measures (PV, Daily P&L, MTD P&L, YTD P&L, Delta P&L) and aggregation dimensions (Book, Portfolio, Currency Pair, Greek, Unit Hedge).', 'risk', '*/10 * * * *', 'skip', 155, 'trading', null, null, 'LIVE'),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), gen_random_uuid(), 1, 'Headline Position (EOD)', 'The headline Greeks at the close: the same set the intraday definition carries, priced from the day''s authorised end of day cut so the figures are authoritative and reproducible. The market risk function signs off on this one, and a later run of the intraday definition never replaces it.', 'risk', '0 18 * * 1-5', 'skip', 156, 'trading', null, null, 'EOD'),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), gen_random_uuid(), 1, 'Spot Greeks', 'P&L and Delta at a grid of spot shift levels, answering what happens to the book if spot moves by a given percentage. The intraday definition reads the live cut, so a desk questions its directional risk while the day is still moving.', 'risk', '*/15 8-17 * * 1-5', 'skip', 160, 'trading', null, null, 'LIVE'),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), gen_random_uuid(), 1, 'Spot Greeks (EOD)', 'The spot shift grid at the close, priced from the day''s authorised end of day cut. Market risk reads it as the authoritative statement of directional risk where the intraday definition states an indicative one.', 'risk', '0 18 * * 1-5', 'skip', 161, 'trading', null, null, 'EOD'),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), gen_random_uuid(), 1, 'Spot Ladder', 'The full forward curve of a currency pair, every tenor''s outright rate, read from the live cut rather than from a valuation. A desk asks for it while quoting and hedging at a named tenor, so it holds a schedule and fires only when the definition is activated.', 'risk', '0 0 31 2 *', 'skip', 170, 'trading', null, null, 'LIVE'),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), gen_random_uuid(), 1, 'Intraday Change', 'How the market data and the risk of a book or portfolio have moved since a configurable reference time, so a desk reads intraday P&L attribution without waiting for the end of day explain run. Priced from the live cut.', 'risk', '*/30 8-17 * * 1-5', 'skip', 190, 'trading', null, null, 'LIVE'),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), gen_random_uuid(), 1, 'Trades Since Last In', 'Every trade booked since a stated date and time, so a desk reviews its morning activity and sees what a colleague added to a shared book. Read from the live cut, on demand.', 'risk', '0 0 31 2 *', 'skip', 195, 'trading', null, null, 'LIVE'),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), gen_random_uuid(), 1, 'Bump and Reprice Rho Ladder', 'The rate value change at each bucket when the curve moves by one shift, discount and projection effects kept apart. It reads the live cut, so a reader questions the shape of the rate risk while the day is still moving. The shift is a setting of the sensitivity document, so the definition states the scope and the cut and never the size.', 'risk', '*/30 8-17 * * 1-5', 'skip', 200, 'trading', null, null, 'LIVE'),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), gen_random_uuid(), 1, 'Bump and Reprice Rho Ladder (EOD)', 'The rate value change at each bucket at the close, discount and projection effects kept apart, priced from the day''s authorised end of day cut. It is the rate risk statement of record, and a later run of the intraday definition never replaces it.', 'risk', '0 18 * * 1-5', 'skip', 201, 'trading', null, null, 'EOD'),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), gen_random_uuid(), 1, 'Bump and Reprice Gamma Ladder', 'The second-order value change in one rate factor at each bucket, taken from the gamma column the engine writes when the sensitivity document switches the second order on. The figure is money and not a curvature per unit, so a reader compares closes and does not rescale it.', 'risk', '0 18 * * 1-5', 'skip', 205, 'trading', null, null, 'EOD'),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), gen_random_uuid(), 1, 'Bump and Reprice Theta Ladder', 'The value change from moving the clock rather than a market, read from the period the sensitivity document states. Its buckets are periods and not curve tenors or volatilities, so it is a ladder of its own.', 'risk', '0 18 * * 1-5', 'skip', 210, 'trading', null, null, 'EOD'),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), gen_random_uuid(), 1, 'Bump and Reprice Cross-gamma Ladder', 'The curvature between two rate factors of one risk class, read from the rows that carry a second factor. The engine writes those rows inside its sensitivity file rather than in a file of their own, so the report reads the pairs where they land.', 'risk', '0 18 * * 1-5', 'skip', 215, 'trading', null, null, 'EOD'),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), gen_random_uuid(), 1, 'Bump and Reprice ATM Vega Ladder', 'The value change at the at-the-money point of each expiry when volatility moves by the shift the document states. It reads the live cut, so a desk sees the shape of its volatility risk between the closes.', 'risk', '*/30 8-17 * * 1-5', 'skip', 220, 'trading', null, null, 'LIVE'),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), gen_random_uuid(), 1, 'Bump and Reprice ATM Vega Ladder (EOD)', 'The at-the-money volatility value change at each expiry at the close, priced from the day''s authorised end of day cut. It is the volatility statement of record.', 'risk', '0 18 * * 1-5', 'skip', 221, 'trading', null, null, 'EOD'),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), gen_random_uuid(), 1, 'Bump and Reprice Surface Vega Ladder', 'The value change at every configured strike of every expiry, which is the surface shifted with its shape held. The catalogue calls the same computation the .1 Triple. It reads the live cut, so a desk sees the smile between the closes.', 'risk', '*/30 8-17 * * 1-5', 'skip', 225, 'trading', null, null, 'LIVE'),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), gen_random_uuid(), 1, 'Bump and Reprice Surface Vega Ladder (EOD)', 'The value change at every configured strike of every expiry at the close, priced from the day''s authorised end of day cut. It is the full-surface statement of record.', 'risk', '0 18 * * 1-5', 'skip', 226, 'trading', null, null, 'EOD'),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), gen_random_uuid(), 1, 'Bump and Reprice Risk-reversal Vega Ladder', 'The call change minus the put change at each expiry, derived from the surface points of a full-surface run rather than asked of the engine. The catalogue calls it the .1 risk reversal. It reads the live cut.', 'risk', '*/30 8-17 * * 1-5', 'skip', 230, 'trading', null, null, 'LIVE'),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), gen_random_uuid(), 1, 'Bump and Reprice Risk-reversal Vega Ladder (EOD)', 'The call change minus the put change at each expiry at the close, derived from the surface points of a full-surface run. It is the skew statement of record.', 'risk', '0 18 * * 1-5', 'skip', 231, 'trading', null, null, 'EOD'),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), gen_random_uuid(), 1, 'Bump and Reprice Butterfly Vega Ladder', 'The wing curvature at each expiry, being half the call change plus half the put change less the at-the-money point. The catalogue calls it the .1 strangle, and the reader takes the butterfly style the pair is stored with rather than a plain average. It reads the live cut.', 'risk', '*/30 8-17 * * 1-5', 'skip', 235, 'trading', null, null, 'LIVE'),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), gen_random_uuid(), 1, 'Bump and Reprice Butterfly Vega Ladder (EOD)', 'The wing curvature at each expiry at the close, from the same run as the risk reversal. It is the wing statement of record.', 'risk', '0 18 * * 1-5', 'skip', 236, 'trading', null, null, 'EOD'),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), gen_random_uuid(), 1, 'Bump and Reprice DV01 Ladder', 'The money value of one basis point at each curve bucket, converted to par instruments so a reader compares one instrument''s risk against another''s. It reads the par sensitivity column the engine writes.', 'risk', '0 18 * * 1-5', 'skip', 240, 'trading', null, null, 'EOD'),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), gen_random_uuid(), 1, 'Bump and Reprice Delta Ladder', 'The first-order value change for one factor at a time, bucketed by the factor key, and the general reader of the ladder family. Seeded, it states the currency pair spots the sensitivity document bumps; every other ladder here is this reader applied to a different block of that document.', 'risk', '0 18 * * 1-5', 'skip', 245, 'trading', null, null, 'EOD');

